        result
    )


if __name__ == "__main__":
    main()

"""
Complete OneDrive Source Container Population

Purpose:
    Performs the controlled initial population of the complete persisted
    OneDrive Source Container Catalog.

Responsibilities:
    - Enumerate the complete OneDrive container hierarchy.
    - Validate the complete Source Container observation.
    - Compare the observation with existing persisted Source Containers.
    - Create a Processing Job for the controlled population.
    - Persist observed OneDrive Source Containers through the approved
      database operation.
    - Report population measurements and results.

Does NOT:
    - Perform ongoing Source Container Refresh.
    - Synchronize OneDrive file content.
    - Create Knowledge Objects.
    - Replace the shared SourceContainerRefreshService.
"""

import json

from datetime import datetime, timezone
from time import perf_counter

from common.security.local_credential_provider import (
    LocalCredentialProvider,
)
from scripts.connectors.ms_graph.onedrive_container_enumerator import (
    OneDriveContainerEnumerator,
)
from scripts.database.database_connection import (
    DatabaseConnection,
)
from scripts.database.processing_job_repository import (
    ProcessingJobRepository,
)
from scripts.database.source_container_repository import (
    SourceContainerRepository,
)
from scripts.database.source_repository import (
    SourceRepository,
)
from scripts.sync.source_container_observation_validator import (
    SourceContainerObservationValidator,
)


SOURCE_NAME = "OneDrive"

MAX_CONTAINER_COUNT = 10000
MAX_PAYLOAD_BYTES = 5 * 1024 * 1024


class ExistingDatabaseConnection:
    """
    Provide an existing authenticated database client to repositories
    that accept a DatabaseConnection-style dependency.
    """

    def __init__(self, client):
        self._client = client

    def connect(self):
        return self._client


def format_duration(seconds):
    """
    Return a readable elapsed-time value.
    """

    if seconds < 60:
        return f"{seconds:.2f} seconds"

    minutes = int(seconds // 60)
    remaining_seconds = seconds % 60

    return (
        f"{minutes} minutes "
        f"{remaining_seconds:.2f} seconds"
    )


def format_bytes(byte_count):
    """
    Return a readable payload-size value.
    """

    if byte_count < 1024:
        return f"{byte_count} bytes"

    kibibytes = byte_count / 1024

    if kibibytes < 1024:
        return f"{kibibytes:.2f} KiB"

    mebibytes = kibibytes / 1024

    return f"{mebibytes:.2f} MiB"


def main():

    total_started_at = perf_counter()

    print()
    print(
        "============================================================"
    )
    print(
        "AlphaOmega Full OneDrive Container Population Test"
    )
    print(
        "============================================================"
    )
    print()

    # ---------------------------------------------------------
    # Database connection and registered Source
    # ---------------------------------------------------------

    credential_provider = (
        LocalCredentialProvider()
    )

    database_connection = (
        DatabaseConnection(
            credential_provider
        )
    )

    client = database_connection.connect()

    source_repository = (
        SourceRepository(client)
    )

    source_id = (
        source_repository.find_id_by_name(
            SOURCE_NAME
        )
    )

    if source_id is None:
        raise RuntimeError(
            "Registered OneDrive Source was not found."
        )

    print(
        "PASS: Registered OneDrive Source resolved."
    )
    print(
        f"  Source ID : {source_id}"
    )
    print()

    source_container_repository = (
        SourceContainerRepository(
            ExistingDatabaseConnection(client)
        )
    )

    # ---------------------------------------------------------
    # Read the existing OneDrive catalog using pagination
    # ---------------------------------------------------------

    existing_rows = (
        source_container_repository.find_by_source(
            source_id
        )
    )

    existing_by_identity = {
        row["source_object_id"]: row
        for row in existing_rows
    }

    print(
        "PASS: Existing OneDrive catalog retrieved."
    )
    print(
        f"  Existing Containers : {len(existing_rows)}"
    )
    print()

    # ---------------------------------------------------------
    # Complete OneDrive enumeration
    # ---------------------------------------------------------

    enumeration_started_at = perf_counter()

    enumerator = (
        OneDriveContainerEnumerator()
    )

    observation = enumerator.enumerate()

    enumeration_seconds = (
        perf_counter()
        - enumeration_started_at
    )

    if (
        observation.get(
            "enumeration_complete"
        )
        is not True
    ):
        raise RuntimeError(
            "OneDrive enumeration is not complete."
        )

    if not observation.get("delta_link"):
        raise RuntimeError(
            "OneDrive enumeration did not return a delta link."
        )

    observed_count = len(
        observation.get(
            "containers",
            [],
        )
    )

    if observed_count == 0:
        raise RuntimeError(
            "SAFETY STOP: Complete OneDrive observation "
            "contained no Containers."
        )

    print(
        "PASS: Complete OneDrive observation received."
    )
    print(
        f"  Observed Containers : {observed_count}"
    )
    print(
        "  Delta Link Present  : True"
    )
    print(
        "  Enumeration Time    : "
        f"{format_duration(enumeration_seconds)}"
    )
    print()

    # ---------------------------------------------------------
    # Validate complete observation
    # ---------------------------------------------------------

    validation_started_at = perf_counter()

    validator = (
        SourceContainerObservationValidator()
    )

    validated_containers = (
        validator.validate(
            observation
        )
    )

    validation_seconds = (
        perf_counter()
        - validation_started_at
    )

    validated_count = len(
        validated_containers
    )

    if validated_count != observed_count:
        raise RuntimeError(
            "Validated Container count does not match "
            "the observed Container count."
        )

    print(
        "PASS: Complete OneDrive observation validated."
    )
    print(
        f"  Validated Containers : {validated_count}"
    )
    print(
        "  Validation Time      : "
        f"{format_duration(validation_seconds)}"
    )
    print()

    # ---------------------------------------------------------
    # Compare current observation with existing catalog
    # ---------------------------------------------------------

    observed_by_identity = {
        container["source_object_id"]:
            container
        for container in validated_containers
    }

    stale_existing_identities = (
        set(existing_by_identity)
        - set(observed_by_identity)
    )

    if stale_existing_identities:
        raise RuntimeError(
            "SAFETY STOP: The existing OneDrive catalog "
            f"contains {len(stale_existing_identities)} "
            "Containers not present in the current observation. "
            "This population test does not deactivate absent "
            "Containers."
        )

    new_container_count = len(
        set(observed_by_identity)
        - set(existing_by_identity)
    )

    existing_container_count = len(
        set(observed_by_identity)
        & set(existing_by_identity)
    )

    print(
        "PASS: Existing catalog is compatible with "
        "the complete observation."
    )
    print(
        f"  Existing Matches : {existing_container_count}"
    )
    print(
        f"  New Containers   : {new_container_count}"
    )
    print()

    # ---------------------------------------------------------
    # Prepare and measure persistence payload
    # ---------------------------------------------------------

    payload_json = json.dumps(
        validated_containers,
        separators=(",", ":"),
        ensure_ascii=False,
    )

    payload_size_bytes = len(
        payload_json.encode("utf-8")
    )

    print(
        "PASS: Full persistence payload prepared."
    )
    print(
        f"  Container Count : {validated_count}"
    )
    print(
        "  Payload Size    : "
        f"{format_bytes(payload_size_bytes)}"
    )
    print()

    # ---------------------------------------------------------
    # Pre-write safety limits
    # ---------------------------------------------------------

    if validated_count > MAX_CONTAINER_COUNT:
        raise RuntimeError(
            "SAFETY STOP: Validated OneDrive Container "
            f"count is {validated_count}, exceeding the "
            f"safety limit of {MAX_CONTAINER_COUNT}. "
            "No database write was attempted."
        )

    if payload_size_bytes > MAX_PAYLOAD_BYTES:
        raise RuntimeError(
            "SAFETY STOP: OneDrive persistence payload "
            f"is {format_bytes(payload_size_bytes)}, exceeding "
            f"the safety limit of "
            f"{format_bytes(MAX_PAYLOAD_BYTES)}. "
            "No database write was attempted."
        )

    print(
        "All pre-write safety checks passed."
    )
    print(
        "Beginning controlled full OneDrive persistence."
    )
    print()

    # ---------------------------------------------------------
    # Processing Job and atomic persistence
    # ---------------------------------------------------------

    processing_job_repository = (
        ProcessingJobRepository(client)
    )

    processing_job_id = None

    try:

        processing_job_id = (
            processing_job_repository.create(
                process_type=(
                    "source_container_refresh"
                ),
                pipeline_version=(
                    "lab8-full-onedrive-test"
                ),
                metadata={
                    "operation":
                        "full_onedrive_population_test",

                    "source":
                        SOURCE_NAME,

                    "observed_container_count":
                        observed_count,

                    "existing_container_count":
                        existing_container_count,

                    "new_container_count":
                        new_container_count,

                    "payload_size_bytes":
                        payload_size_bytes,
                },
            )
        )

        print(
            "PASS: Processing Job created."
        )
        print(
            "  Processing Job ID : "
            f"{processing_job_id}"
        )
        print()

        observed_at = (
            datetime.now(
                timezone.utc
            ).isoformat()
        )

        persistence_started_at = perf_counter()

        response = (
            client.rpc(
                "upsert_source_containers",
                {
                    "p_source_id":
                        source_id,

                    "p_processing_job_id":
                        processing_job_id,

                    "p_observed_at":
                        observed_at,

                    "p_containers":
                        validated_containers,
                },
            ).execute()
        )

        persistence_seconds = (
            perf_counter()
            - persistence_started_at
        )

        if response.data != validated_count:
            raise RuntimeError(
                "Persistence RPC did not report the "
                "validated number of Containers. "
                f"Expected {validated_count}, "
                f"received {response.data}."
            )

        print(
            "PASS: Atomic persistence completed."
        )
        print(
            f"  RPC Processed    : {response.data}"
        )
        print(
            "  Persistence Time : "
            f"{format_duration(persistence_seconds)}"
        )
        print()

        # -----------------------------------------------------
        # Verify the complete persisted OneDrive catalog
        # -----------------------------------------------------

        verification_started_at = perf_counter()

        persisted_rows = (
            source_container_repository.find_by_source(
                source_id
            )
        )

        persisted_by_identity = {
            row["source_object_id"]:
                row
            for row in persisted_rows
        }

        if len(persisted_rows) != validated_count:
            raise RuntimeError(
                "Full catalog verification failed. "
                f"Expected {validated_count} persisted "
                "OneDrive Containers, found "
                f"{len(persisted_rows)}."
            )

        missing_identities = (
            set(observed_by_identity)
            - set(persisted_by_identity)
        )

        unexpected_identities = (
            set(persisted_by_identity)
            - set(observed_by_identity)
        )

        if missing_identities:
            raise RuntimeError(
                "Full catalog verification failed. "
                f"{len(missing_identities)} observed "
                "Containers are missing from the database."
            )

        if unexpected_identities:
            raise RuntimeError(
                "Full catalog verification failed. "
                f"{len(unexpected_identities)} unexpected "
                "OneDrive Containers are present."
            )

        hierarchy_mismatches = []
        name_mismatches = []
        inactive_containers = []
        job_mismatches = []

        for source_object_id, observed in (
            observed_by_identity.items()
        ):

            persisted = persisted_by_identity[
                source_object_id
            ]

            if (
                persisted.get(
                    "parent_source_object_id"
                )
                != observed.get(
                    "parent_source_object_id"
                )
            ):
                hierarchy_mismatches.append(
                    source_object_id
                )

            if (
                persisted.get("name")
                != observed.get("name")
            ):
                name_mismatches.append(
                    source_object_id
                )

            if persisted.get("is_active") is not True:
                inactive_containers.append(
                    source_object_id
                )

            if (
                str(
                    persisted.get(
                        "last_seen_processing_job_id"
                    )
                )
                != str(processing_job_id)
            ):
                job_mismatches.append(
                    source_object_id
                )

        if hierarchy_mismatches:
            raise RuntimeError(
                "Full catalog verification failed. "
                f"{len(hierarchy_mismatches)} Containers "
                "have incorrect parent identities."
            )

        if name_mismatches:
            raise RuntimeError(
                "Full catalog verification failed. "
                f"{len(name_mismatches)} Containers "
                "have incorrect names."
            )

        if inactive_containers:
            raise RuntimeError(
                "Full catalog verification failed. "
                f"{len(inactive_containers)} Containers "
                "are inactive."
            )

        if job_mismatches:
            raise RuntimeError(
                "Full catalog verification failed. "
                f"{len(job_mismatches)} Containers "
                "have incorrect Processing Job attribution."
            )

        verification_seconds = (
            perf_counter()
            - verification_started_at
        )

        processing_job_repository.complete(
            processing_job_id
        )

        total_seconds = (
            perf_counter()
            - total_started_at
        )

        print(
            f"PASS: All {validated_count} OneDrive "
            "Containers verified."
        )
        print(
            "PASS: All persisted Containers are active."
        )
        print(
            "PASS: All Containers reference the current "
            "Processing Job."
        )
        print(
            "PASS: Processing Job completed."
        )
        print()

        print(
            "============================================================"
        )
        print(
            "Full OneDrive Population Measurements"
        )
        print(
            "============================================================"
        )
        print(
            f"  Containers       : {validated_count}"
        )
        print(
            f"  Previously Saved : {existing_container_count}"
        )
        print(
            f"  Newly Inserted   : {new_container_count}"
        )
        print(
            "  Payload Size     : "
            f"{format_bytes(payload_size_bytes)}"
        )
        print(
            "  Enumeration Time : "
            f"{format_duration(enumeration_seconds)}"
        )
        print(
            "  Validation Time  : "
            f"{format_duration(validation_seconds)}"
        )
        print(
            "  Persistence Time : "
            f"{format_duration(persistence_seconds)}"
        )
        print(
            "  Verification Time: "
            f"{format_duration(verification_seconds)}"
        )
        print(
            "  Total Time       : "
            f"{format_duration(total_seconds)}"
        )
        print()

        print(
            "FULL ONEDRIVE CONTAINER POPULATION TEST: PASS"
        )
        print()

    except Exception as error:

        if processing_job_id is not None:

            try:
                processing_job_repository.fail(
                    processing_job_id,
                    error,
                )

            except Exception as job_error:
                print(
                    "WARNING: Unable to mark Processing "
                    "Job failed:"
                )
                print(
                    job_error
                )

        raise


if __name__ == "__main__":
    main()

"""
AlphaOmega Source Browsing Service

Purpose:
    Provides the application-facing capability for browsing registered
    Sources and their persisted Source Container hierarchy.

Responsibilities:
    - List enabled registered Sources.
    - Validate that a requested Source exists and is enabled.
    - Retrieve active persisted Source Containers for a Source.
    - Construct the application-facing Source Container hierarchy.
    - Expose AlphaOmega Source and Source Container identities to callers.

Does NOT:
    - Access the database directly.
    - Communicate with a Source of Truth.
    - Enumerate or refresh Source Containers.
    - Synchronize content.
    - Create Processing Jobs or Synchronization Runs.
    - Perform UI presentation.
"""


class SourceBrowsingService:
    """
    Provide Source and Source Container browsing to application clients.
    """

    def __init__(
        self,
        *,
        source_repository,
        source_container_repository,
    ):
        """
        Initialize Source browsing dependencies.
        """

        if source_repository is None:
            raise ValueError(
                "source_repository is required."
            )

        if source_container_repository is None:
            raise ValueError(
                "source_container_repository is required."
            )

        self._source_repository = (
            source_repository
        )

        self._source_container_repository = (
            source_container_repository
        )

    def list_sources(
        self,
    ):
        """
        Return enabled registered Sources available for browsing.

        Only application-facing Source data is returned.
        """

        sources = (
            self._source_repository
            .find_enabled()
        )

        return tuple(
            {
                "source_id":
                    source[
                        "id"
                    ],

                "name":
                    source[
                        "name"
                    ],

                "source_type":
                    source.get(
                        "source_type"
                    ),

                "description":
                    source.get(
                        "description"
                    ),
            }
            for source
            in sources
        )

    def browse_source(
        self,
        source_id,
    ):
        """
        Return the active persisted Source Container hierarchy
        for one registered enabled Source.

        Source-native identifiers are used internally to reconstruct
        hierarchy.

        They are not exposed through the returned application model.

        The AlphaOmega Source Container UUID is the application-facing
        Container identity.
        """

        if (
            source_id is None
            or not str(
                source_id
            ).strip()
        ):
            raise ValueError(
                "source_id is required."
            )

        source_id = (
            str(
                source_id
            ).strip()
        )

        source = (
            self._source_repository
            .find_by_id(
                source_id
            )
        )

        if source is None:
            raise ValueError(
                "Source does not exist."
            )

        if (
            source.get(
                "is_enabled"
            )
            is not True
        ):
            raise ValueError(
                "Source is not enabled."
            )

        containers = (
            self
            ._source_container_repository
            .find_active_by_source(
                source_id
            )
        )

        roots = (
            self._build_hierarchy(
                containers
            )
        )

        return {
            "source": {
                "source_id":
                    source[
                        "id"
                    ],

                "name":
                    source[
                        "name"
                    ],

                "source_type":
                    source.get(
                        "source_type"
                    ),

                "description":
                    source.get(
                        "description"
                    ),
            },

            "container_count":
                len(
                    containers
                ),

            "roots":
                roots,
        }

    @staticmethod
    def _build_hierarchy(
        containers,
    ):
        """
        Convert the flat persisted Source Container catalog into
        application-facing hierarchical data.

        Source-native identity is used only while reconstructing
        parent-child relationships.
        """

        source_object_map = {}

        for container in containers:

            source_object_id = (
                container.get(
                    "source_object_id"
                )
            )

            if (
                source_object_id is None
                or not str(
                    source_object_id
                ).strip()
            ):
                raise RuntimeError(
                    "Source Container is missing source_object_id."
                )

            source_object_id = (
                str(
                    source_object_id
                ).strip()
            )

            if (
                source_object_id
                in source_object_map
            ):
                raise RuntimeError(
                    "Duplicate Source Container source identity."
                )

            source_object_map[
                source_object_id
            ] = {
                "record":
                    container,

                "node": {
                    "source_container_id":
                        container[
                            "id"
                        ],

                    "name":
                        container[
                            "name"
                        ],

                    "children":
                        [],
                },
            }

        roots = []

        for entry in (
            source_object_map.values()
        ):

            record = (
                entry[
                    "record"
                ]
            )

            node = (
                entry[
                    "node"
                ]
            )

            parent_source_object_id = (
                record.get(
                    "parent_source_object_id"
                )
            )

            if (
                parent_source_object_id
                is None
                or not str(
                    parent_source_object_id
                ).strip()
            ):
                roots.append(
                    node
                )

                continue

            parent_source_object_id = (
                str(
                    parent_source_object_id
                ).strip()
            )

            parent_entry = (
                source_object_map.get(
                    parent_source_object_id
                )
            )

            if parent_entry is None:
                raise RuntimeError(
                    "Active Source Container references "
                    "a parent that is not present in the "
                    "active Source Container catalog."
                )

            parent_entry[
                "node"
            ][
                "children"
            ].append(
                node
            )

        SourceBrowsingService._sort_hierarchy(
            roots
        )

        return tuple(
            roots
        )

    @staticmethod
    def _sort_hierarchy(
        nodes,
    ):
        """
        Sort one hierarchy level and all descendants by name.
        """

        nodes.sort(
            key=lambda node:
                str(
                    node[
                        "name"
                    ]
                ).casefold()
        )

        for node in nodes:

            SourceBrowsingService._sort_hierarchy(
                node[
                    "children"
                ]
            )

            node[
                "children"
            ] = tuple(
                node[
                    "children"
                ]
            )

"""
AlphaOmega Synchronization Admission Service

Purpose:
    Validates one SynchronizationRequest against the persisted Source and
    Source Container catalogs.

Responsibilities:
    - Validate that the requested Source exists.
    - Validate that the requested Source is enabled.
    - Validate that the requested Source Container exists.
    - Validate that the Source Container is active.
    - Validate that the Source Container belongs to the requested Source.
    - Return the persisted identities required by later synchronization
      capabilities.

Does NOT:
    - Communicate with a Source of Truth.
    - Refresh Source Containers.
    - Detect synchronization overlap.
    - Reserve synchronization execution.
    - Create Processing Jobs or Synchronization Runs.
    - Invoke SynchronizationOrchestrator.
"""


class SynchronizationAdmissionService:
    """
    Validate persisted synchronization request identity and scope.
    """

    def __init__(
        self,
        *,
        source_repository,
        source_container_repository,
    ):
        """
        Initialize synchronization admission dependencies.
        """

        if source_repository is None:
            raise ValueError(
                "source_repository is required."
            )

        if source_container_repository is None:
            raise ValueError(
                "source_container_repository is required."
            )

        self._source_repository = (
            source_repository
        )

        self._source_container_repository = (
            source_container_repository
        )

    def validate(
        self,
        request,
    ):
        """
        Validate one SynchronizationRequest against persisted
        AlphaOmega Source and Source Container state.

        Returns an application-owned admitted request description.

        This method performs no database writes.
        """

        if request is None:
            raise ValueError(
                "request is required."
            )

        source_id = getattr(
            request,
            "source_id",
            None,
        )

        source_container_id = getattr(
            request,
            "source_container_id",
            None,
        )

        if (
            source_id is None
            or not str(
                source_id
            ).strip()
        ):
            raise ValueError(
                "request.source_id is required."
            )

        if (
            source_container_id is None
            or not str(
                source_container_id
            ).strip()
        ):
            raise ValueError(
                "request.source_container_id is required."
            )

        source_id = (
            str(
                source_id
            ).strip()
        )

        source_container_id = (
            str(
                source_container_id
            ).strip()
        )

        source = (
            self._source_repository
            .find_by_id(
                source_id
            )
        )

        if source is None:
            raise ValueError(
                "Requested Source does not exist."
            )

        if (
            source.get(
                "is_enabled"
            )
            is not True
        ):
            raise ValueError(
                "Requested Source is not enabled."
            )

        source_container = (
            self
            ._source_container_repository
            .find_by_id(
                source_container_id
            )
        )

        if source_container is None:
            raise ValueError(
                "Requested Source Container does not exist."
            )

        container_source_id = (
            source_container.get(
                "source_id"
            )
        )

        if (
            container_source_id is None
            or str(
                container_source_id
            ).strip()
            != source_id
        ):
            raise ValueError(
                "Requested Source Container does not belong "
                "to the requested Source."
            )

        if (
            source_container.get(
                "is_active"
            )
            is not True
        ):
            raise ValueError(
                "Requested Source Container is not active."
            )

        return {
            "source_id":
                source_id,

            "source_container_id":
                source_container_id,

            "source_name":
                source[
                    "name"
                ],

            "source_object_id":
                source_container[
                    "source_object_id"
                ],

            "container_name":
                source_container[
                    "name"
                ],
        }

"""
OneDrive File Format Inventory

Purpose:
    Produces a read-only inventory of file formats present across the
    configured OneDrive Source of Truth.

Verifies:
    - The production GraphConnector can enumerate the configured OneDrive.
    - File extensions present in OneDrive can be identified and counted.
    - Supported and unsupported extraction formats can be inspected against
      the live source inventory.

Does NOT:
    - Modify OneDrive.
    - Write to the AlphaOmega database.
    - Extract or persist Knowledge Objects.
    - Change synchronization behavior.
"""

from collections import defaultdict
from pathlib import Path

from scripts.connectors.ms_graph.graph_connector import (
    GraphConnector,
)

from scripts.extraction.text_extractor import (
    TextExtractor,
)


# ============================================================================
# Configuration
# ============================================================================

EXAMPLE_LIMIT = 5


# ============================================================================
# Helpers
# ============================================================================

def get_extension(file_name):
    """
    Return a normalized lowercase file extension.

    Files without an extension are represented explicitly so they
    are not silently lost from the inventory.
    """

    if not file_name:
        return "[NO NAME]"

    extension = (
        Path(file_name)
        .suffix
        .lower()
    )

    if not extension:
        return "[NO EXTENSION]"

    return extension


def get_display_path(raw_object):
    """
    Resolve the best available source path for inventory output.
    """

    connector_metadata = (
        raw_object.get(
            "connector_metadata"
        )
        or {}
    )

    object_path = (
        connector_metadata.get(
            "object_path"
        )
    )

    if object_path:
        return object_path

    source_path = (
        connector_metadata.get(
            "source_path"
        )
    )

    raw_graph_object = (
        raw_object.get(
            "raw_object"
        )
        or {}
    )

    name = (
        raw_graph_object.get(
            "name"
        )
        or "[UNNAMED]"
    )

    if source_path:
        return f"{source_path}/{name}"

    return name


# ============================================================================
# Inventory
# ============================================================================

def build_format_inventory(
    connector_section,
):
    """
    Build file-format counts and representative paths from the
    completed OneDrive Connector output.
    """

    format_counts = defaultdict(int)
    format_examples = defaultdict(list)

    container_count = 0
    content_count = 0

    for item in (
        connector_section.raw_objects
    ):

        source_object_type = (
            item.get(
                "source_object_type"
            )
        )

        raw_graph_object = (
            item.get(
                "raw_object"
            )
            or {}
        )

        # Microsoft Graph DriveItems identify folders with a
        # "folder" facet and files with a "file" facet.
        if (
            "folder"
            in raw_graph_object
        ):
            container_count += 1
            continue

        if (
            "file"
            not in raw_graph_object
        ):
            # Preserve visibility of unusual DriveItems rather than
            # accidentally classifying them as normal files.
            continue

        content_count += 1

        file_name = (
            raw_graph_object.get(
                "name"
            )
        )

        extension = (
            get_extension(
                file_name
            )
        )

        format_counts[
            extension
        ] += 1

        if (
            len(
                format_examples[
                    extension
                ]
            )
            < EXAMPLE_LIMIT
        ):
            format_examples[
                extension
            ].append(
                get_display_path(
                    item
                )
            )

    return {
        "format_counts":
            dict(
                format_counts
            ),

        "format_examples":
            dict(
                format_examples
            ),

        "container_count":
            container_count,

        "content_count":
            content_count,
    }


# ============================================================================
# Reporting
# ============================================================================

def print_summary(
    inventory,
):
    """
    Print the complete extension inventory.
    """

    format_counts = (
        inventory[
            "format_counts"
        ]
    )

    format_examples = (
        inventory[
            "format_examples"
        ]
    )

    supported_extensions = {
        extension.lower()
        for extension
        in TextExtractor.supported_extensions
    }

    print()

    print(
        "=" * 100
    )

    print(
        "ONEDRIVE FILE FORMAT INVENTORY"
    )

    print(
        "=" * 100
    )

    print()

    print(
        f"CONTAINER objects : "
        f"{inventory['container_count']}"
    )

    print(
        f"CONTENT objects   : "
        f"{inventory['content_count']}"
    )

    print(
        f"Unique extensions : "
        f"{len(format_counts)}"
    )

    print()

    print(
        "-" * 100
    )

    print(
        f"{'EXTENSION':<20}"
        f"{'COUNT':>10}   "
        f"{'ALPHAOMEGA EXTRACTION':<30}"
    )

    print(
        "-" * 100
    )

    sorted_formats = sorted(
        format_counts.items(),
        key=lambda item: (
            -item[1],
            item[0],
        ),
    )

    supported_file_count = 0
    unsupported_file_count = 0

    supported_format_count = 0
    unsupported_format_count = 0

    for (
        extension,
        count,
    ) in sorted_formats:

        is_supported = (
            extension
            in supported_extensions
        )

        if is_supported:
            status = "SUPPORTED"
            supported_file_count += count
            supported_format_count += 1

        else:
            status = "UNSUPPORTED"
            unsupported_file_count += count
            unsupported_format_count += 1

        print(
            f"{extension:<20}"
            f"{count:>10}   "
            f"{status:<30}"
        )

    print()

    print(
        "=" * 100
    )

    print(
        "EXTRACTION COVERAGE"
    )

    print(
        "=" * 100
    )

    print()

    print(
        f"Supported extensions   : "
        f"{supported_format_count}"
    )

    print(
        f"Unsupported extensions : "
        f"{unsupported_format_count}"
    )

    print()

    print(
        f"Files currently supported   : "
        f"{supported_file_count}"
    )

    print(
        f"Files currently unsupported : "
        f"{unsupported_file_count}"
    )

    total_files = (
        supported_file_count
        + unsupported_file_count
    )

    if total_files:

        coverage = (
            supported_file_count
            / total_files
            * 100
        )

        print(
            f"Current extraction coverage : "
            f"{coverage:.2f}%"
        )

    # ========================================================================
    # Unsupported Formats
    # ========================================================================

    print()

    print(
        "=" * 100
    )

    print(
        "UNSUPPORTED FORMAT EXAMPLES"
    )

    print(
        "=" * 100
    )

    unsupported_found = False

    for (
        extension,
        count,
    ) in sorted_formats:

        if (
            extension
            in supported_extensions
        ):
            continue

        unsupported_found = True

        print()

        print(
            f"{extension} "
            f"({count} files)"
        )

        examples = (
            format_examples.get(
                extension,
                []
            )
        )

        for path in examples:

            print(
                f"  {path}"
            )

    if not unsupported_found:

        print()

        print(
            "No unsupported file formats found."
        )

    # ========================================================================
    # Supported Formats
    # ========================================================================

    print()

    print(
        "=" * 100
    )

    print(
        "SUPPORTED FORMAT EXAMPLES"
    )

    print(
        "=" * 100
    )

    for (
        extension,
        count,
    ) in sorted_formats:

        if (
            extension
            not in supported_extensions
        ):
            continue

        print()

        print(
            f"{extension} "
            f"({count} files)"
        )

        examples = (
            format_examples.get(
                extension,
                []
            )
        )

        for path in examples:

            print(
                f"  {path}"
            )


# ============================================================================
# Main
# ============================================================================

def main():

    print()

    print(
        "=" * 100
    )

    print(
        "AlphaOmega OneDrive File Format Inventory"
    )

    print(
        "=" * 100
    )

    print()

    print(
        "READ-ONLY ANALYSIS"
    )

    print(
        "No file content will be retrieved."
    )

    print(
        "No AlphaOmega database writes will occur."
    )

    print()

    print(
        "Enumerating complete OneDrive..."
    )

    connector = (
        GraphConnector()
    )

    connector_section = (
        connector.run(
            "OneDrive"
        )
    )

    if not (
        connector_section.is_locked
    ):
        raise RuntimeError(
            "OneDrive ConnectorSection "
            "was not locked."
        )

    print(
        "PASS: Production OneDrive Connector "
        "enumeration completed."
    )

    print()

    print(
        "Building format inventory..."
    )

    inventory = (
        build_format_inventory(
            connector_section
        )
    )

    print_summary(
        inventory
    )

    print()

    print(
        "=" * 100
    )

    print(
        "FINAL RESULT"
    )

    print(
        "=" * 100
    )

    print()

    print(
        "PASS: OneDrive format inventory completed."
    )

    print(
        "No AlphaOmega database writes were performed."
    )

    print()


if __name__ == "__main__":
    main()

"""
Live AlphaOmega Container Reconciliation Test

Purpose:
    Validates Source Container reconciliation against the live persisted
    AlphaOmega OneDrive container catalog.

Verifies:
    - Live OneDrive container observations can be enumerated and validated.
    - Persisted Source Containers can be retrieved for comparison.
    - Reconciliation correctly compares observed and persisted containers.
    - Reconciliation produces the expected catalog change classifications.

Does NOT:
    - Apply reconciliation results to the database.
    - Modify the Source Container Catalog.
    - Perform content synchronization.
    - Create Knowledge Objects.
"""

from common.security.local_credential_provider import (
    LocalCredentialProvider,
)
from scripts.connectors.ms_graph.onedrive_container_enumerator import (
    OneDriveContainerEnumerator,
)
from scripts.database.database_connection import (
    DatabaseConnection,
)
from scripts.database.source_container_repository import (
    SourceContainerRepository,
)
from scripts.database.source_repository import (
    SourceRepository,
)
from scripts.sync.source_container_observation_validator import (
    SourceContainerObservationValidator,
)
from scripts.sync.source_container_reconciler import (
    SourceContainerReconciler,
)


SOURCE_NAME = "OneDrive"

ALPHAOMEGA_ROOT_ID = (
    "70EE5AA1D6A4DA1F!s9c76b7e6703145539f4f257f446477f7"
)


def select_subtree(
    containers,
    root_source_object_id,
):
    """
    Return the selected root Container and all descendants.
    """

    containers_by_id = {
        container["source_object_id"]: container
        for container in containers
    }

    if root_source_object_id not in containers_by_id:
        raise RuntimeError(
            "Approved AlphaOmega root is not present "
            "in the validated OneDrive observation."
        )

    containers_by_parent = {}

    for container in containers:

        parent_id = container.get(
            "parent_source_object_id"
        )

        containers_by_parent.setdefault(
            parent_id,
            [],
        ).append(
            container
        )

    subtree = []
    pending = [
        root_source_object_id
    ]
    visited = set()

    while pending:

        source_object_id = pending.pop()

        if source_object_id in visited:
            continue

        visited.add(
            source_object_id
        )

        container = containers_by_id.get(
            source_object_id
        )

        if container is None:
            raise RuntimeError(
                "Subtree references a Container "
                "missing from the validated observation."
            )

        subtree.append(
            container
        )

        for child in containers_by_parent.get(
            source_object_id,
            [],
        ):
            pending.append(
                child["source_object_id"]
            )

    return subtree


def main():

    print()
    print(
        "============================================================"
    )
    print(
        "AlphaOmega Live Source Container Reconciliation Test"
    )
    print(
        "============================================================"
    )
    print()

    # ---------------------------------------------------------
    # Database connection
    # ---------------------------------------------------------

    credential_provider = (
        LocalCredentialProvider()
    )

    database_connection = (
        DatabaseConnection(
            credential_provider
        )
    )

    client = (
        database_connection.connect()
    )

    # ---------------------------------------------------------
    # Resolve registered OneDrive Source
    # ---------------------------------------------------------

    source_repository = (
        SourceRepository(client)
    )

    source_id = (
        source_repository.find_id_by_name(
            SOURCE_NAME
        )
    )

    if source_id is None:
        raise RuntimeError(
            "Registered OneDrive Source was not found."
        )

    print(
        "PASS: Registered OneDrive Source resolved."
    )
    print(
        f"  Source ID : {source_id}"
    )
    print()

    # ---------------------------------------------------------
    # Fresh complete OneDrive observation
    # ---------------------------------------------------------

    enumerator = (
        OneDriveContainerEnumerator()
    )

    observation = (
        enumerator.enumerate()
    )

    if (
        observation.get(
            "enumeration_complete"
        )
        is not True
    ):
        raise RuntimeError(
            "OneDrive enumeration is not complete."
        )

    print(
        "PASS: Complete OneDrive observation received."
    )
    print(
        f"  Observed Containers : "
        f"{len(observation['containers'])}"
    )
    print()

    # ---------------------------------------------------------
    # Validate complete observation
    # ---------------------------------------------------------

    validator = (
        SourceContainerObservationValidator()
    )

    validated_containers = (
        validator.validate(
            observation
        )
    )

    print(
        "PASS: OneDrive observation validated."
    )
    print(
        f"  Validated Containers : "
        f"{len(validated_containers)}"
    )
    print()

    # ---------------------------------------------------------
    # Select current AlphaOmega subtree
    # ---------------------------------------------------------

    alphaomega_observed = (
        select_subtree(
            validated_containers,
            ALPHAOMEGA_ROOT_ID,
        )
    )

    print(
        "PASS: Current AlphaOmega subtree selected."
    )
    print(
        f"  Observed AlphaOmega Containers : "
        f"{len(alphaomega_observed)}"
    )
    print()

    # ---------------------------------------------------------
    # Read persisted Source Container Catalog
    # ---------------------------------------------------------

    source_container_repository = (
        SourceContainerRepository(
            database_connection
        )
    )

    persisted_all = (
        source_container_repository.find_by_source(
            source_id
        )
    )

    # Only compare persisted records that belong to the
    # AlphaOmega subtree population.
    #
    # The initial population occurred from the previous
    # AlphaOmega observation. Its identities should therefore
    # overlap the current subtree. A previously persisted
    # AlphaOmega Container that has since disappeared must also
    # remain in the reconciliation input so it can become ABSENT.
    #
    # Start from the approved root and reconstruct the persisted
    # subtree using persisted parent relationships.

    persisted_by_id = {
        container["source_object_id"]: container
        for container in persisted_all
    }

    persisted_children = {}

    for container in persisted_all:

        parent_id = container.get(
            "parent_source_object_id"
        )

        persisted_children.setdefault(
            parent_id,
            [],
        ).append(
            container
        )

    alphaomega_existing = []

    if ALPHAOMEGA_ROOT_ID in persisted_by_id:

        pending = [
            ALPHAOMEGA_ROOT_ID
        ]

        visited = set()

        while pending:

            source_object_id = pending.pop()

            if source_object_id in visited:
                continue

            visited.add(
                source_object_id
            )

            container = persisted_by_id.get(
                source_object_id
            )

            if container is None:
                continue

            alphaomega_existing.append(
                container
            )

            for child in persisted_children.get(
                source_object_id,
                [],
            ):
                pending.append(
                    child["source_object_id"]
                )

    else:
        raise RuntimeError(
            "Persisted AlphaOmega root was not found."
        )

    print(
        "PASS: Persisted AlphaOmega catalog read."
    )
    print(
        f"  Persisted AlphaOmega Containers : "
        f"{len(alphaomega_existing)}"
    )
    print()

    # ---------------------------------------------------------
    # Reconcile
    # ---------------------------------------------------------

    reconciler = (
        SourceContainerReconciler()
    )

    result = (
        reconciler.reconcile(
            observed_containers=alphaomega_observed,
            existing_containers=alphaomega_existing,
        )
    )

    print(
        "Reconciliation result:"
    )
    print(
        f"  NEW         : {len(result['new'])}"
    )
    print(
        f"  EXISTING    : {len(result['existing'])}"
    )
    print(
        f"  REAPPEARING : {len(result['reappearing'])}"
    )
    print(
        f"  ABSENT      : {len(result['absent'])}"
    )
    print()

    # ---------------------------------------------------------
    # Identity proof
    # ---------------------------------------------------------

    existing_count = (
        len(result["existing"])
    )

    if existing_count == 0:
        raise RuntimeError(
            "No persisted AlphaOmega identities were "
            "recognized by reconciliation."
        )

    for pair in result["existing"]:

        existing = pair["existing"]

        if not existing.get("id"):
            raise RuntimeError(
                "An EXISTING Container does not have "
                "a persistent AlphaOmega UUID."
            )

    print(
        "PASS: Persisted Source identities were recognized."
    )
    print(
        "PASS: EXISTING Containers retain AlphaOmega UUIDs."
    )
    print()
    print(
        "ALPHAOMEGA LIVE RECONCILIATION TEST: PASS"
    )
    print()
    print(
        "READ ONLY: No database records were changed."
    )
    print()


