# ============================================================================
# Shared Helpers
# ============================================================================

def build_connector_section(
    source_name,
    connector_objects,
):
    """
    Build a ConnectorSection for deterministic testing.
    """

    section = ConnectorSection(
        source_name
    )

    section.connection_succeeded = True

    section.raw_objects = (
        connector_objects
    )

    section.raw_metadata = {
        "enumeration_complete":
            True,

        "test_mode":
            True,

        "objects_retrieved":
            len(connector_objects),
    }

    section.lock()

    return section


def expected_name(
    source_object_type,
    raw_object,
):
    """
    Determine expected canonical name.
    """

    if source_object_type == "page":

        title = raw_object.get(
            "title"
        )

        if (
            title is None
            or not str(title).strip()
        ):

            return "Untitled"

        return str(title).strip()

    return (
        raw_object.get(
            "displayName"
        )
        or raw_object.get(
            "name"
        )
    )


def expected_type(
    source_object_type,
    raw_object,
):
    """
    Determine expected canonical object type.
    """

    if source_object_type in (
        "notebook",
        "sectionGroup",
        "section",
        "driveRoot",
    ):

        return "CONTAINER"

    if source_object_type == "page":

        return "CONTENT"

    if source_object_type == "driveItem":

        if "folder" in raw_object:

            return "CONTAINER"

        return "CONTENT"

    return None


def find_exact_object(
    objects,
    field_name,
    field_value,
    description,
):
    """
    Find exactly one source object using a known field value.
    """

    matches = [
        item
        for item in objects
        if item.get(
            field_name
        ) == field_value
    ]

    if len(matches) != 1:

        raise RuntimeError(
            f"Expected exactly one {description} "
            f"named '{field_value}'. "
            f"Found {len(matches)}."
        )

    return matches[0]


# ============================================================================
# OneDrive Sample Retrieval
# ============================================================================

def get_onedrive_sample(
    connector,
):
    """
    Retrieve Writings and recursively retrieve every descendant.
    """

    root_children = (
        connector._get_collection(
            "/me/drive/root/children"
        )
    )

    writings_matches = [
        item
        for item in root_children
        if (
            item.get("name")
            == ONEDRIVE_TEST_FOLDER
            and "folder"
            in item
        )
    ]

    if len(writings_matches) != 1:

        raise RuntimeError(
            "Expected exactly one OneDrive "
            "Writings folder."
        )

    raw_objects = []

    def crawl(
        item,
    ):
        """
        Recursively crawl every descendant of Writings.
        """

        raw_objects.append(
            connector._wrap_object(
                "driveItem",
                item,
            )
        )

        if "folder" not in item:

            return

        item_id = item.get(
            "id"
        )

        if not item_id:

            raise RuntimeError(
                "OneDrive folder is missing "
                "its object ID."
            )

        children = (
            connector._get_collection(
                "/me/drive/items/"
                f"{item_id}/children"
            )
        )

        for child in children:

            crawl(
                child
            )

    crawl(
        writings_matches[0]
    )

    return build_connector_section(
        "onedrive",
        raw_objects,
    )


