def get_onenote_notebook(
    connector,
    notebook_name,
):
    """
    Retrieve one exact OneNote notebook including its sections and
    section groups.
    """

    notebooks = (
        connector._get_collection(
            "/me/onenote/notebooks"
            "?$expand=sections,"
            "sectionGroups($expand=sections)"
        )
    )

    return find_exact_object(
        notebooks,
        "displayName",
        notebook_name,
        "OneNote notebook",
    )


def add_notebook(
    connector,
    notebook,
    raw_objects,
    sections,
    section_ids,
    section_group_ids,
    only_section_name=None,
):
    """
    Add a notebook and selected section hierarchy using the same
    production Connector hierarchy functions.
    """

    notebook_id = (
        notebook.get(
            "id"
        )
    )

    notebook_name = (
        notebook.get(
            "displayName"
        )
    )

    if not notebook_id:

        raise RuntimeError(
            f"Notebook '{notebook_name}' "
            "is missing its ID."
        )

    raw_objects.append(
        connector._wrap_object(
            "notebook",
            notebook,
            connector_metadata={
                "source_parent_object_id":
                    None,

                "source_path":
                    None,

                "object_path":
                    notebook_name,

                "hierarchy_verified":
                    True,
            },
        )
    )

    notebook_sections = (
        notebook.get(
            "sections",
            [],
        )
    )

    if only_section_name is not None:

        notebook_sections = [
            section
            for section
            in notebook_sections
            if section.get(
                "displayName"
            ) == only_section_name
        ]

        if len(notebook_sections) != 1:

            raise RuntimeError(
                f"Expected exactly one section "
                f"'{only_section_name}' in notebook "
                f"'{notebook_name}'. "
                f"Found {len(notebook_sections)}."
            )

    for section in notebook_sections:

        connector._add_onenote_section(
            section=section,
            raw_objects=raw_objects,
            sections=sections,
            section_ids=section_ids,
            parent_object_id=(
                notebook_id
            ),
            parent_path=(
                notebook_name
            ),
        )

    if only_section_name is None:

        for section_group in notebook.get(
            "sectionGroups",
            [],
        ):

            connector._add_onenote_section_group(
                section_group=(
                    section_group
                ),
                raw_objects=raw_objects,
                sections=sections,
                section_ids=section_ids,
                section_group_ids=(
                    section_group_ids
                ),
                parent_object_id=(
                    notebook_id
                ),
                parent_path=(
                    notebook_name
                ),
            )


def get_onenote_sample(
    connector,
):
    """
    Retrieve the two known OneNote regression datasets.
    """

    raw_objects = []

