# ============================================================================
# Correlation Validation
# ============================================================================

def validate_correlation_input(
    connector_section,
    connector_snapshot,
    translation_input,
):
    """
    Validate the Synchronization correlation boundary.
    """

    failures = []

    # ------------------------------------------------------------------------
    # ConnectorSection must remain locked
    # ------------------------------------------------------------------------

    if connector_section.is_locked is not True:

        failures.append(
            {
                "object":
                    connector_section.source_name,

                "field":
                    "connector_section_locked",

                "expected":
                    True,

                "actual":
                    connector_section.is_locked,
            }
        )

    # ------------------------------------------------------------------------
    # Connector raw objects must remain unchanged
    # ------------------------------------------------------------------------

    if (
        list(
            connector_section.raw_objects
        )
        != connector_snapshot
    ):

        failures.append(
            {
                "object":
                    connector_section.source_name,

                "field":
                    "connector_raw_objects_unchanged",

                "expected":
                    "unchanged",

                "actual":
                    "modified",
            }
        )

    # ------------------------------------------------------------------------
    # Record count must remain one-for-one
    # ------------------------------------------------------------------------

    if (
        len(
            translation_input.raw_objects
        )
        != len(
            connector_section.raw_objects
        )
    ):

        failures.append(
            {
                "object":
                    connector_section.source_name,

                "field":
                    "correlation_record_count",

                "expected":
                    len(
                        connector_section.raw_objects
                    ),

                "actual":
                    len(
                        translation_input.raw_objects
                    ),
            }
        )

    correlation_ids = []

    # ------------------------------------------------------------------------
    # Validate every correlated object
    # ------------------------------------------------------------------------

    for index, correlated_object in enumerate(
        translation_input.raw_objects
    ):

        correlation_id = (
            correlated_object.get(
                "correlation_id"
            )
        )

        correlation_ids.append(
            correlation_id
        )

        # --------------------------------------------------------------------
        # UUID must exist and be valid
        # --------------------------------------------------------------------

        try:

            parsed_uuid = UUID(
                str(
                    correlation_id
                )
            )

            if str(
                parsed_uuid
            ) != str(
                correlation_id
            ):

                raise ValueError(
                    "UUID string is not canonical."
                )

        except Exception:

            failures.append(
                {
                    "object":
                        index,

                    "field":
                        "correlation_id",

                    "expected":
                        "valid canonical UUID",

                    "actual":
                        correlation_id,
                }
            )

        # --------------------------------------------------------------------
        # Connector source information must be preserved
        # --------------------------------------------------------------------

        if (
            index
            < len(
                connector_section.raw_objects
            )
        ):

            connector_object = (
                connector_section.raw_objects[
                    index
                ]
            )

            if (
                correlated_object.get(
                    "source_object_type"
                )
                != connector_object.get(
                    "source_object_type"
                )
            ):

                failures.append(
                    {
                        "object":
                            index,

                        "field":
                            "source_object_type_preserved",

                        "expected":
                            connector_object.get(
                                "source_object_type"
                            ),

                        "actual":
                            correlated_object.get(
                                "source_object_type"
                            ),
                    }
                )

            if (
                correlated_object.get(
                    "raw_object"
                )
                != connector_object.get(
                    "raw_object"
                )
            ):

                failures.append(
                    {
                        "object":
                            index,

                        "field":
                            "raw_object_preserved",

                        "expected":
                            "Connector raw_object",

                        "actual":
                            "different raw_object",
                    }
                )

            if (
                correlated_object.get(
                    "connector_metadata",
                    {},
                )
                != connector_object.get(
                    "connector_metadata",
                    {},
                )
            ):

                failures.append(
                    {
                        "object":
                            index,

                        "field":
                            "connector_metadata_preserved",

                        "expected":
                            connector_object.get(
                                "connector_metadata",
                                {},
                            ),

                        "actual":
                            correlated_object.get(
                                "connector_metadata",
                                {},
                            ),
                    }
                )

    # ------------------------------------------------------------------------
    # UUIDs must be unique within this synchronization batch
    # ------------------------------------------------------------------------

    if (
        len(
            correlation_ids
        )
        != len(
            set(
                correlation_ids
            )
        )
    ):

        failures.append(
            {
                "object":
                    connector_section.source_name,

                "field":
                    "correlation_id_uniqueness",

                "expected":
                    len(
                        correlation_ids
                    ),

                "actual":
                    len(
                        set(
                            correlation_ids
                        )
                    ),
            }
        )

    return failures


# ============================================================================
# General Pipeline Validation
# ============================================================================

def validate_pipeline(
    source_name,
    connector_section,
):
    """
    Apply synchronization correlation, translate every Connector object,
    and validate canonical values and correlation identity.
    """

    connector_snapshot = list(
        connector_section.raw_objects
    )

    translation_input = TranslationInput(
        connector_section
    )

    failures = validate_correlation_input(
        connector_section=(
            connector_section
        ),
        connector_snapshot=(
            connector_snapshot
        ),
        translation_input=(
            translation_input
        ),
    )

    translator = GraphTranslator()

    translator_section = (
        translator.run(
            translation_input
        )
    )

    # ------------------------------------------------------------------------
    # Build correlation lookup before source-object lookup.
    # ------------------------------------------------------------------------

    correlation_by_source_id = {}

    for correlated_object in (
        translation_input.raw_objects
    ):

        raw_object = (
            correlated_object[
                "raw_object"
            ]
        )

        object_id = raw_object.get(
            "id"
        )

        correlation_by_source_id[
            object_id
        ] = correlated_object[
            "correlation_id"
        ]

    translated_by_id = {
        record.source_object_id:
            record
        for record
        in translator_section.translated_records
    }

    # ------------------------------------------------------------------------
    # Record accounting
    # ------------------------------------------------------------------------

    if (
        len(
            translator_section.translated_records
        )
        + len(
            translator_section.record_errors
        )
        != len(
            connector_section.raw_objects
        )
    ):

        failures.append(
            {
                "object":
                    source_name,

                "field":
                    "record_accounting",

                "expected":
                    len(
                        connector_section.raw_objects
                    ),

                "actual":
                    (
                        len(
                            translator_section
                            .translated_records
                        )
                        + len(
                            translator_section
                            .record_errors
                        )
                    ),
            }
        )

    # ------------------------------------------------------------------------
    # Validate every object
    # ------------------------------------------------------------------------

    for connector_object in (
        connector_section.raw_objects
    ):

        source_object_type = (
            connector_object[
                "source_object_type"
            ]
        )

        raw_object = (
            connector_object[
                "raw_object"
            ]
        )

        connector_metadata = (
            connector_object.get(
                "connector_metadata",
                {},
            )
        )

        object_id = raw_object.get(
            "id"
        )

        name = expected_name(
            source_object_type,
            raw_object,
        )

        record = (
            translated_by_id.get(
                object_id
            )
        )

        if record is None:

            failures.append(
                {
                    "object":
                        name,

                    "field":
                        "translated_record",

                    "expected":
                        "present",

                    "actual":
                        "missing",
                }
            )

            continue

        expected_correlation_id = (
            correlation_by_source_id.get(
                object_id
            )
        )

        comparisons = {
            "correlation_id":
                (
                    expected_correlation_id,
                    record.correlation_id,
                ),

            "name":
                (
                    name,
                    record.name,
                ),

            "object_type":
                (
                    expected_type(
                        source_object_type,
                        raw_object,
                    ),
                    record.object_type,
                ),

            "source_object_id":
                (
                    object_id,
                    record.source_object_id,
                ),

            "source_created_at":
                (
                    raw_object.get(
                        "createdDateTime"
                    ),
                    record.source_created_at,
                ),

            "source_modified_at":
                (
                    raw_object.get(
                        "lastModifiedDateTime"
                    ),
                    record.source_modified_at,
                ),
        }

        if (
            "source_parent_object_id"
            in connector_metadata
        ):

            comparisons[
                "source_parent_object_id"
            ] = (
                connector_metadata.get(
                    "source_parent_object_id"
                ),
                record.source_parent_object_id,
            )

        elif source_name == "onedrive":

            parent_reference = (
                raw_object.get(
                    "parentReference"
                )
                or {}
            )

            comparisons[
                "source_parent_object_id"
            ] = (
                parent_reference.get(
                    "id"
                ),
                record.source_parent_object_id,
            )

        if (
            "source_path"
            in connector_metadata
        ):

            comparisons[
                "source_path"
            ] = (
                connector_metadata.get(
                    "source_path"
                ),
                record.source_path,
            )

        for (
            field_name,
            values,
        ) in comparisons.items():

            expected_value = (
                values[0]
            )

            actual_value = (
                values[1]
            )

            if (
                expected_value
                != actual_value
            ):

                failures.append(
                    {
                        "object":
                            name,

                        "object_id":
                            object_id,

                        "field":
                            field_name,

                        "expected":
                            expected_value,

                        "actual":
                            actual_value,
                    }
                )

    return (
        translator_section,
        failures,
    )


