def get_unique_record(
    translator_section,
    name,
):
    """
    Return exactly one translated record having the requested name.
    """

    matches = [
        record
        for record
        in translator_section.translated_records
        if record.name == name
    ]

    if len(matches) != 1:

        return (
            None,
            {
                "object":
                    name,

                "field":
                    "baseline_lookup",

                "expected":
                    "exactly one translated record",

                "actual":
                    len(matches),
            },
        )

    return (
        matches[0],
        None,
    )


def validate_games_hierarchy(
    translator_section,
):
