        if (
            child.source_path
            != expected_path
        ):

            failures.append(
                {
                    "object":
                        child_name,

                    "field":
                        "source_path",

                    "expected":
                        expected_path,

                    "actual":
                        child.source_path,
                }
            )

    return failures


