        )
    )

    if error:

        failures.append(
            error
        )

        return failures

    if (
        child_page.source_parent_object_id
        != parent_page.source_object_id
    ):

        failures.append(
            {
                "object":
                    "Armor",

                "field":
                    "source_parent_object_id",

                "expected":
                    parent_page.source_object_id,

                "actual":
                    child_page.source_parent_object_id,
            }
        )

    expected_path = (
        "Mimic's Tavern/"
        "Homebrew/"
        "Selune Armor"
    )

    if (
        child_page.source_path
        != expected_path
    ):

        failures.append(
            {
                "object":
                    "Armor",

                "field":
                    "source_path",

                "expected":
                    expected_path,

                "actual":
                    child_page.source_path,
            }
        )

    parent_hierarchy = (
        parent_page.metadata.get(
            "connector_hierarchy",
            {},
        )
    )

    child_hierarchy = (
        child_page.metadata.get(
            "connector_hierarchy",
            {},
        )
    )

    parent_level = (
        parent_hierarchy.get(
            "page_level"
        )
    )

    child_level = (
        child_hierarchy.get(
            "page_level"
        )
    )

    if parent_level != 0:

        failures.append(
            {
                "object":
                    "Selune Armor",

                "field":
                    "page_level",

                "expected":
                    0,

                "actual":
                    parent_level,
            }
        )

    if child_level != 2:

        failures.append(
            {
                "object":
                    "Armor",

                "field":
                    "page_level",

                "expected":
                    2,

                "actual":
                    child_level,
            }
        )

    parent_order = (
        parent_hierarchy.get(
            "page_order"
        )
    )

    child_order = (
        child_hierarchy.get(
            "page_order"
        )
    )

    if (
        isinstance(
            parent_order,
            int,
        )
        and isinstance(
            child_order,
            int,
        )
    ):

        if child_order <= parent_order:

            failures.append(
                {
                    "object":
                        "Armor",

                    "field":
                        "page_order",

                    "expected":
                        (
                            "greater than Selune "
                            "Armor page order"
                        ),

                    "actual":
                        child_order,
                }
            )

    else:

        failures.append(
            {
                "object":
                    "Armor",

                "field":
                    "page_order",

                "expected":
                    "integer ordering values",

                "actual":
                    {
                        "Selune Armor":
                            parent_order,

                        "Armor":
                            child_order,
                    },
            }
        )

    return failures


def validate_untitled_pages(
