):

    response = (
        client
        .table(
            "processing_jobs"
        )
        .insert(
            {
                "process_type":
                    "sync",

                "status":
                    "running",

                "pipeline_version":
                    "lab7-targeted-live-modified",

                "metadata":
                    {
                        "test_type":
                            "targeted_live_modified",

                        "targets":
                            [
                                ONEDRIVE_FILE_NAME,
                                ONENOTE_PAGE_NAME,
                            ],
                    },
            }
        )
        .execute()
    )

    records = response.data

    if (
        records is None
        or len(records) != 1
    ):
        raise RuntimeError(
            "Unable to create MODIFIED test Processing Job."
        )

    print(
        "PASS: MODIFIED test Processing Job created."
    )

    return records[0]["id"]


def complete_processing_job(
    client,
    processing_job_id,
):

    completed_at = (
        datetime.now(
            timezone.utc
        ).isoformat()
    )

    response = (
        client
        .table(
            "processing_jobs"
        )
        .update(
            {
                "status":
                    "completed",

                "completed_at":
                    completed_at,

                "error_message":
                    None,
            }
        )
        .eq(
            "id",
            processing_job_id,
        )
        .execute()
    )

    if (
        response.data is None
        or len(response.data) != 1
    ):
        raise RuntimeError(
            "Unable to complete MODIFIED Processing Job."
        )

    print(
        "PASS: MODIFIED test Processing Job completed."
    )


def fail_processing_job(
    client,
    processing_job_id,
    error,
):

    try:

        completed_at = (
            datetime.now(
                timezone.utc
            ).isoformat()
        )

        client.table(
            "processing_jobs"
        ).update(
            {
                "status":
                    "failed",

                "completed_at":
                    completed_at,

                "error_message":
                    str(error),
            }
        ).eq(
            "id",
            processing_job_id,
        ).execute()

        print(
            "PASS: Failed Processing Job closed."
        )

    except Exception as cleanup_error:

