    print(
        f"PASS: Existing Knowledge Object located for "
        f"'{expected_title}'."
    )

    print(
        f"  Knowledge Object ID : "
        f"{knowledge_object['id']}"
    )

    print(
        f"  Previous hash       : "
        f"{knowledge_object['content_hash']}"
    )

    print(
        f"  Previous modified   : "
        f"{knowledge_object['source_modified_at']}"
    )

    return (
        source_id,
        knowledge_object,
    )


