        )
        .eq(
            "processing_job_id",
            processing_job_id,
        )
        .eq(
            "knowledge_object_id",
            knowledge_object_id,
        )
        .execute()
    )

    records = response.data

    if (
        records is None
        or len(records) != 1
    ):

        raise RuntimeError(
            f"Expected exactly one new Sync History event for "
            f"'{expected_title}'."
        )

    record = records[0]

    if (
        record["source_id"]
        != source_id
    ):

