def verify_database_result(
    *,
    client,
    source_id,
    previous_knowledge_object,
    processing_job_id,
    expected_hash,
):
    """
    Verify Orchestration updated the existing Knowledge Object
    rather than creating a duplicate.
    """

    response = (
        client
        .table(
            "knowledge_objects"
        )
        .select(
            "id,"
            "source_id,"
            "source_object_id,"
            "title,"
            "content_hash,"
            "source_modified_at"
        )
        .eq(
            "source_id",
            source_id,
        )
        .eq(
            "source_object_id",
            ONEDRIVE_OBJECT_ID,
        )
        .execute()
    )

    records = response.data

    if (
        records is None
        or len(
            records
        )
        != 1
    ):
        raise RuntimeError(
            "Expected exactly one Knowledge Object "
            "after Orchestration."
        )

    persisted = records[0]

    if (
        persisted["id"]
        != previous_knowledge_object["id"]
