        )

    print(
        "PASS: Existing Knowledge Object updated in place."
    )

    print(
        f"  Knowledge Object ID : "
        f"{persisted['id']}"
    )

    print(
        f"  New hash            : "
        f"{persisted['content_hash']}"
    )

    # ------------------------------------------------------------------------
    # Sync History
    # ------------------------------------------------------------------------

    history_response = (
        client
        .table(
            "sync_history"
        )
        .select(
            "id,"
            "source_id,"
            "knowledge_object_id,"
            "processing_job_id,"
            "sync_event"
        )
        .eq(
            "processing_job_id",
            processing_job_id,
        )
        .eq(
            "knowledge_object_id",
            persisted["id"],
        )
        .execute()
    )

    history_records = (
        history_response.data
    )

    if (
        history_records is None
        or len(
            history_records
        )
        != 1
    ):
        raise RuntimeError(
            "Expected exactly one Sync History event "
            "for the Orchestrator run."
        )

    history = (
        history_records[0]
