def verify_processing_job(
    *,
    client,
    processing_job_id,
):
    """
    Verify Orchestration completed its Processing Job.
    """

    response = (
        client
        .table(
            "processing_jobs"
        )
        .select(
            "id,"
            "process_type,"
            "status,"
            "pipeline_version,"
            "completed_at,"
            "error_message"
        )
        .eq(
            "id",
            processing_job_id,
        )
        .execute()
    )

    records = response.data

    if (
        records is None
        or len(
            records
        )
        != 1
    ):
        raise RuntimeError(
            "Processing Job could not be verified."
        )

    job = (
        records[0]
    )

    if (
        job["status"]
        != "completed"
    ):
        raise RuntimeError(
            "Processing Job was not completed."
        )

    if (
        job["process_type"]
        != "sync"
    ):
        raise RuntimeError(
