def get_existing_knowledge_object(
    *,
    source_repository,
    knowledge_object_repository,
):

    source_id = (
        source_repository.find_id_by_name(
            "OneNote"
        )
    )

    if source_id is None:
        raise RuntimeError(
            "OneNote Source is not registered."
        )

    knowledge_object = (
        knowledge_object_repository
        .find_by_source_identity(
            source_id=source_id,
            source_object_id=(
                ONENOTE_PAGE_ID
            ),
        )
    )

    if knowledge_object is None:
        raise RuntimeError(
            "Controlled OneNote Knowledge Object "
            "does not exist."
        )

    if (
        knowledge_object["title"]
        != ONENOTE_PAGE_NAME
    ):
        raise RuntimeError(
            "Controlled OneNote Knowledge Object "
            "title mismatch."
        )

    print(
        "PASS: Existing controlled OneNote "
        "Knowledge Object located."
    )

    print(
        f"  Knowledge Object ID : "
        f"{knowledge_object['id']}"
    )

    print(
        f"  Previous hash       : "
        f"{knowledge_object['content_hash']}"
    )

    print(
        f"  Previous modified   : "
        f"{knowledge_object['source_modified_at']}"
    )

    return (
        source_id,
        knowledge_object,
    )


# ============================================================================
# Database Verification
# ============================================================================


def verify_database_result(
    *,
    client,
    source_id,
    previous_knowledge_object,
    processing_job_id,
    expected_hash,
):

    response = (
        client
        .table(
            "knowledge_objects"
        )
        .select(
            "id,"
            "source_id,"
            "source_object_id,"
            "title,"
            "content_hash,"
            "source_modified_at"
        )
        .eq(
            "source_id",
            source_id,
        )
        .eq(
            "source_object_id",
            ONENOTE_PAGE_ID,
        )
        .execute()
    )

    records = (
        response.data
    )

    if (
        records is None
        or len(records) != 1
    ):
        raise RuntimeError(
            "Expected exactly one OneNote Knowledge Object "
            "after Orchestration."
        )

    persisted = (
        records[0]
    )

    if (
        persisted["id"]
        != previous_knowledge_object["id"]
    ):
        raise RuntimeError(
            "OneNote Knowledge Object identity changed."
        )

    if (
        persisted["content_hash"]
        != expected_hash
    ):
        raise RuntimeError(
            "Persisted OneNote content hash does not "
            "match Extraction output."
        )

    print(
        "PASS: Existing OneNote Knowledge Object "
        "updated in place."
    )

    print(
        f"  Knowledge Object ID : "
        f"{persisted['id']}"
    )

    print(
        f"  New hash            : "
        f"{persisted['content_hash']}"
    )

    history_response = (
        client
        .table(
            "sync_history"
        )
        .select(
            "id,"
            "source_id,"
            "knowledge_object_id,"
            "processing_job_id,"
            "sync_event"
        )
        .eq(
            "processing_job_id",
            processing_job_id,
        )
        .eq(
            "knowledge_object_id",
            persisted["id"],
        )
        .execute()
    )

    history_records = (
        history_response.data
    )

    if (
        history_records is None
        or len(history_records) != 1
    ):
        raise RuntimeError(
            "Expected exactly one OneNote Sync History "
            "event for this Orchestrator run."
        )

    history = (
        history_records[0]
    )

    if (
        history["source_id"]
        != source_id
    ):
        raise RuntimeError(
            "OneNote Sync History source mismatch."
        )

    if (
        str(
            history["sync_event"]
        ).lower()
        != "modified"
    ):
        raise RuntimeError(
            "Expected Modified OneNote Sync History event."
        )

    print(
        "PASS: Modified OneNote Sync History event verified."
    )


