        .table(
            "processing_jobs"
        )
        .select(
            "id,"
            "process_type,"
            "status,"
            "pipeline_version,"
            "completed_at,"
            "error_message"
        )
        .eq(
            "id",
            processing_job_id,
        )
        .execute()
    )

    records = (
        response.data
    )

    if (
        records is None
        or len(records) != 1
    ):
        raise RuntimeError(
            "Processing Job could not be verified."
        )

    job = (
        records[0]
    )

    if (
        job["status"]
        != "completed"
    ):
        raise RuntimeError(
            "Processing Job was not completed."
        )

    if (
        job["process_type"]
        != "sync"
    ):
        raise RuntimeError(
            "Processing Job process type incorrect."
        )

    if (
        job["pipeline_version"]
        != "lab7-live-orchestrator-onenote-v1"
    ):
        raise RuntimeError(
            "Processing Job pipeline version incorrect."
        )

    if (
        job["completed_at"]
        is None
    ):
        raise RuntimeError(
            "Processing Job has no completion timestamp."
        )

    if (
        job["error_message"]
        is not None
    ):
        raise RuntimeError(
            "Completed Processing Job contains an error."
        )

    print(
        "PASS: Orchestrator Processing Job completed correctly."
    )


