PIPELINE_VERSION = (
    "lab7-live-onenote-section-modified-v1"
)


# ============================================================================
# Bounded Connector
# ============================================================================

class HouseRulesOneNoteConnector(
    GraphConnector
):

    @staticmethod
    def _find_named_object(
        objects,
        expected_name,
        name_field,
        object_type,
    ):

        matches = []

        for item in objects:

            actual_name = item.get(
                name_field
            )

            if (
                actual_name
                and actual_name.strip().casefold()
                == expected_name.casefold()
            ):
                matches.append(
                    item
                )

        if not matches:
            raise RuntimeError(
                f"{object_type} not found: "
                f"'{expected_name}'."
            )

        if len(matches) > 1:
            raise RuntimeError(
                f"Multiple {object_type} objects found "
                f"with the name '{expected_name}'."
            )

        return matches[0]

    def run(
        self,
        source_name,
    ):

        if (
            source_name is None
            or str(source_name).lower()
            != "onenote"
        ):
            raise ValueError(
                "Controlled Connector supports "
                "OneNote only."
            )

        notebooks = (
            self._get_collection(
                "/me/onenote/notebooks"
            )
        )

        notebook = (
            self._find_named_object(
                notebooks,
                NOTEBOOK_NAME,
                "displayName",
                "notebook",
            )
        )

        notebook_id = (
            notebook.get("id")
        )

        if not notebook_id:
            raise RuntimeError(
                "Notebook is missing Graph ID."
            )

        sections = (
            self._get_collection(
                "/me/onenote/notebooks/"
                f"{notebook_id}/sections"
            )
        )

        section = (
            self._find_named_object(
                sections,
                SECTION_NAME,
                "displayName",
                "section",
            )
        )

        section_id = (
            section.get("id")
        )

        if not section_id:
            raise RuntimeError(
                "Section is missing Graph ID."
            )

        live_section = (
            self._get_json(
                "/me/onenote/sections/"
                f"{section_id}"
            )
        )

        if (
            live_section.get("id")
            != section_id
        ):
            raise RuntimeError(
                "Section identity mismatch."
            )

        section_modified_at = (
            live_section.get(
                "lastModifiedDateTime"
            )
        )

        if not section_modified_at:
            raise RuntimeError(
                "Section is missing "
                "lastModifiedDateTime."
            )

        raw_objects = []

        section_path = (
            self._join_source_path(
                NOTEBOOK_NAME,
                SECTION_NAME,
            )
        )

        raw_objects.append(
            self._wrap_object(
                "section",
                live_section,
                connector_metadata={
                    "source_parent_object_id":
                        notebook_id,

                    "source_path":
                        NOTEBOOK_NAME,

                    "object_path":
                        section_path,

                    "hierarchy_verified":
                        True,
                },
            )
        )

        section_context = {
            "raw_object":
                live_section,

            "object_path":
                section_path,
        }

        self._enumerate_onenote_section_pages(
            section_context=section_context,
            raw_objects=raw_objects,
        )

        pages = [
            item
            for item in raw_objects
            if (
                item.get(
                    "source_object_type"
                )
                == "page"
            )
        ]

        if (
            len(pages)
            != EXPECTED_PAGE_COUNT
        ):
            raise RuntimeError(
                "Unexpected page count.\n"
                f"Expected: {EXPECTED_PAGE_COUNT}\n"
                f"Actual:   {len(pages)}"
            )

        page_ids = [
            page["raw_object"].get("id")
            for page in pages
        ]

        if (
            len(set(page_ids))
            != EXPECTED_PAGE_COUNT
        ):
            raise RuntimeError(
                "Page identities are not unique."
            )

        if (
            len(raw_objects)
            != EXPECTED_ASSOCIATION_COUNT
        ):
            raise RuntimeError(
                "Unexpected Connector object count."
            )

        connector_section = (
            ConnectorSection(
                "onenote"
            )
        )

        connector_section.raw_objects = (
            raw_objects
        )

        connector_section.raw_metadata = {
            "enumeration_complete":
                True,

            "test_mode":
                True,

            "target_notebook":
                NOTEBOOK_NAME,

            "target_section":
                SECTION_NAME,

            "target_section_id":
                section_id,

            "source_section_modified_at":
                section_modified_at,

            "pages_retrieved":
                len(pages),

            "objects_retrieved":
                len(raw_objects),
        }

        connector_section.connection_succeeded = (
            True
        )

        self._validate_completed_section(
            connector_section
        )

        connector_section.lock()

        print(
            "PASS: Controlled Connector enumerated "
            "House Rules."
        )

        print(
            f"  Section modified : "
            f"{section_modified_at}"
        )

        print(
            f"  Pages            : {len(pages)}"
        )

        print(
            f"  Connector objects: {len(raw_objects)}"
        )

        return connector_section


