    existing = []

    for page in pages:

        raw_page = (
            page[
                "raw_object"
            ]
        )

        page_id = (
            raw_page.get(
                "id"
            )
        )

        page_title = (
            raw_page.get(
                "title"
            )
            or "Untitled"
        )

        knowledge_object = (
            knowledge_object_repository
            .find_by_source_identity(
                source_id=source_id,
                source_object_id=page_id,
            )
        )

        if knowledge_object is not None:

            existing.append(
                {
                    "title":
                        page_title,

                    "source_object_id":
                        page_id,

                    "knowledge_object_id":
                        knowledge_object.get(
                            "id"
                        ),
                }
            )

    if existing:

        print()

        print(
            "PRECONDITION FAILURE:"
        )

        print(
            "One or more House Rules pages already "
            "exist in AlphaOmega."
        )

        for record in existing:

            print(
                f"  {record['title']} : "
                f"{record['knowledge_object_id']}"
            )

        raise RuntimeError(
            "Synchronization aborted before writes "
            "because the NEW-only precondition failed."
        )

    print(
