            "pages_retrieved":
                len(pages),

            "objects_retrieved":
                len(raw_objects),
        }

        connector_section.connection_succeeded = (
            True
        )

        self._validate_completed_section(
            connector_section
        )

        connector_section.lock()

        print(
            "PASS: Controlled live Connector "
