# ============================================================================
# Database Verification
# ============================================================================

def verify_database_unchanged(
    *,
    client,
    source_id,
    snapshot,
    processing_job_id,
):

    for (
        source_object_id,
        previous,
    ) in snapshot.items():

        response = (
            client
            .table(
                "knowledge_objects"
            )
            .select(
                "id,"
                "content_hash,"
                "source_modified_at"
            )
            .eq(
                "source_id",
                source_id,
            )
            .eq(
                "source_object_id",
                source_object_id,
            )
            .execute()
        )

        records = (
            response.data
            or []
        )

        if len(records) != 1:
            raise RuntimeError(
                "Knowledge Object could not "
                "be uniquely verified.\n"
                f"Page: {previous['title']}"
            )

        current = (
            records[0]
        )

        if (
            current["id"]
            != previous["id"]
        ):
            raise RuntimeError(
                "Knowledge Object identity changed.\n"
                f"Page: {previous['title']}"
            )

        if (
            current["content_hash"]
            != previous["content_hash"]
        ):
            raise RuntimeError(
                "UNCHANGED Knowledge Object hash changed.\n"
                f"Page: {previous['title']}"
            )

        if (
            current["source_modified_at"]
            != previous["source_modified_at"]
        ):
            raise RuntimeError(
                "UNCHANGED Knowledge Object timestamp changed.\n"
                f"Page: {previous['title']}"
            )

    print(
        "PASS: All 16 Knowledge Objects remained "
        "unchanged in the database."
    )

    history_response = (
        client
        .table(
            "sync_history"
        )
        .select(
            "id,"
            "knowledge_object_id,"
            "sync_event"
        )
        .eq(
            "processing_job_id",
            processing_job_id,
        )
        .execute()
    )

    history = (
        history_response.data
        or []
    )

    if history:
        raise RuntimeError(
            "UNCHANGED synchronization unexpectedly "
            "created Sync History events.\n"
            f"Actual: {len(history)}"
        )

    print(
        "PASS: No Sync History events created."
    )


# ============================================================================
# Processing Job Verification
# ============================================================================

def verify_processing_job(
    *,
    client,
    processing_job_id,
):

    response = (
        client
        .table(
            "processing_jobs"
        )
        .select(
            "id,"
            "process_type,"
            "status,"
            "pipeline_version,"
            "completed_at,"
            "error_message"
        )
        .eq(
            "id",
            processing_job_id,
        )
        .execute()
    )

    records = (
        response.data
        or []
    )

    if len(records) != 1:
        raise RuntimeError(
            "Processing Job could not "
            "be uniquely verified."
        )

    job = (
        records[0]
    )

    if job["process_type"] != "sync":
        raise RuntimeError(
            "Unexpected Processing Job process_type."
        )

    if job["status"] != "completed":
        raise RuntimeError(
            "Processing Job did not complete."
        )

    if (
        job["pipeline_version"]
        != PIPELINE_VERSION
    ):
        raise RuntimeError(
            "Unexpected Processing Job "
            "pipeline_version."
        )

    if job["completed_at"] is None:
        raise RuntimeError(
            "Processing Job has no completed_at."
        )

    if job["error_message"] is not None:
        raise RuntimeError(
            "Completed Processing Job contains "
            "an error_message."
        )

    print(
        "PASS: Processing Job completed correctly."
    )


