    print(
        "AlphaOmega Source Container Reconciler Test"
    )
    print(
        "============================================================"
    )
    print()

    reconciler = (
        SourceContainerReconciler()
    )

    existing_containers = [
        {
            "id": "AO-A",
            "source_object_id": "A",
            "name": "Existing",
            "parent_source_object_id": None,
            "is_active": True,
        },
        {
            "id": "AO-B",
