            "source_object_id": "C",
            "name": "Inactive",
            "parent_source_object_id": "A",
            "is_active": False,
        },
        {
            "id": "AO-D",
            "source_object_id": "D",
            "name": "Will Disappear",
            "parent_source_object_id": "A",
            "is_active": True,
        },
    ]

    observed_containers = [
        {
            "source_object_id": "A",
            "name": "Existing",
            "parent_source_object_id": None,
        },
        {
            "source_object_id": "B",
            "name": "Renamed",
            "parent_source_object_id": "A",
        },
        {
            "source_object_id": "C",
            "name": "Inactive Returns",
            "parent_source_object_id": "A",
        },
        {
            "source_object_id": "E",
            "name": "Brand New",
            "parent_source_object_id": "A",
        },
    ]

    result = (
        reconciler.reconcile(
            observed_containers=(
                observed_containers
            ),
            existing_containers=(
