class FakeTranslatorSection(
    FakeLockedSection
):

    def __init__(
        self,
        translated_records,
    ):
        super().__init__()

        self.translated_records = (
            translated_records
        )


class FakeTranslator:

    def run(
        self,
        translation_input,
    ):

        if (
            len(
                translation_input.raw_objects
            )
            != 2
        ):
            raise RuntimeError(
                "Translator did not receive "
                "both Connector objects."
            )

        translated_records = []

        for correlated_object in (
            translation_input.raw_objects
        ):

            correlation_id = (
                correlated_object[
                    "correlation_id"
                ]
            )

            raw_object = (
                correlated_object[
                    "raw_object"
                ]
            )

            source_object_type = (
                correlated_object[
                    "source_object_type"
                ]
            )

            if (
                source_object_type
                == "folder"
            ):
                object_type = (
                    CONTAINER
                )

            elif (
                source_object_type
                == "file"
            ):
                object_type = (
                    CONTENT
                )

            else:
                raise RuntimeError(
                    "Unexpected source object type."
                )

            translated_records.append(
                FakeTranslatorRecord(
                    correlation_id=(
                        correlation_id
                    ),
                    source_object_id=(
                        raw_object["id"]
                    ),
                    object_type=(
                        object_type
                    ),
                )
            )

        return FakeTranslatorSection(
            translated_records
        )


