class SyntheticConnector:
    """
    Produce three canonical synthetic Connector objects.

    These objects intentionally follow the actual Connector ->
    TranslationInput boundary contract:

        source_object_type
        raw_object
        connector_metadata
    """

    def __init__(self):
        self.run_calls = []

    def run(
        self,
        source_name,
    ):
        self.run_calls.append(
            source_name
        )

        raw_objects = (
            {
                "source_object_type":
                    "driveItem",

                "raw_object":
                    {
                        "id":
                            "source-new",

                        "name":
                            "New Object",

                        "file":
                            {
                                "mimeType":
                                    "text/plain",
                            },
                    },

                "connector_metadata":
                    {},
            },

            {
                "source_object_type":
                    "driveItem",

                "raw_object":
                    {
                        "id":
                            "source-modified",

                        "name":
                            "Modified Object",

                        "file":
                            {
                                "mimeType":
                                    "text/plain",
                            },
                    },

                "connector_metadata":
                    {},
            },

            {
                "source_object_type":
                    "driveItem",

                "raw_object":
                    {
                        "id":
                            "source-unchanged",

                        "name":
                            "Unchanged Object",

                        "file":
                            {
                                "mimeType":
                                    "text/plain",
                            },
                    },

                "connector_metadata":
                    {},
            },
        )

        return SyntheticSection(
            source_name=source_name,
            raw_objects=raw_objects,
        )


# ============================================================================
# Synthetic Translator
# ============================================================================


class SyntheticTranslator:
    """
    Translate correlated Connector objects while preserving
    orchestration correlation identity.
    """

    def __init__(self):
        self.received_translation_input = None

    def run(
        self,
        translation_input,
    ):
        self.received_translation_input = (
            translation_input
        )

        records = []

        for correlated_object in (
            translation_input.raw_objects
        ):
            raw_object = (
                correlated_object[
                    "raw_object"
                ]
            )

            records.append(
                SimpleNamespace(
                    correlation_id=(
                        correlated_object[
                            "correlation_id"
                        ]
                    ),

                    source_name=
                        "OneDrive",

                    source_object_id=(
                        raw_object[
                            "id"
                        ]
                    ),

                    source_parent_object_id=
                        None,

                    source_path=
                        None,

                    source_url=
                        None,

                    name=(
                        raw_object[
                            "name"
                        ]
                    ),

                    object_type=
                        "CONTENT",

                    source_created_at=
                        None,

                    source_modified_at=
                        None,

                    metadata=
                        {},
                )
            )

        return SyntheticSection(
            translated_records=tuple(
                records
            ),
            record_errors=(),
        )


# ============================================================================
# Synthetic Discovery
# ============================================================================


class SyntheticDiscoveryService:
    """
    Classify the three synthetic records as NEW, MODIFIED,
    and UNCHANGED.
    """

    def __init__(self):
        self.received_translator_section = None

    def run(
        self,
        translator_section,
    ):
        self.received_translator_section = (
            translator_section
        )

        discovery_records = []

        for translator_record in (
            translator_section.translated_records
        ):
            source_object_id = (
                translator_record.source_object_id
            )

            if (
                source_object_id
                == "source-new"
            ):
                sync_state = (
                    SyncState.NEW
                )

                requires_extraction = (
                    True
                )

                knowledge_object_id = (
                    None
                )

                previous_content_hash = (
                    None
                )

            elif (
                source_object_id
                == "source-modified"
            ):
                sync_state = (
                    SyncState.MODIFIED
                )

                requires_extraction = (
                    True
                )

                knowledge_object_id = (
                    "ko-modified"
                )

                previous_content_hash = (
                    "old-modified-hash"
                )

            elif (
                source_object_id
                == "source-unchanged"
            ):
                sync_state = (
                    SyncState.UNCHANGED
                )

                requires_extraction = (
                    False
                )

                knowledge_object_id = (
                    "ko-unchanged"
                )

                previous_content_hash = (
                    "unchanged-hash"
                )

            else:
                raise RuntimeError(
                    "Unexpected synthetic object."
                )

            discovery_records.append(
                SimpleNamespace(
                    correlation_id=(
                        translator_record
                        .correlation_id
                    ),

                    sync_state=(
                        sync_state
                    ),

                    requires_extraction=(
                        requires_extraction
                    ),

                    knowledge_object_id=(
                        knowledge_object_id
                    ),

                    previous_content_hash=(
                        previous_content_hash
                    ),

                    comparison_reason=
                        None,
                )
            )

        return SyntheticSection(
            discovery_records=tuple(
                discovery_records
            ),
            record_errors=(),
        )


