class SyntheticProcessingJobRepository:
    """
    Capture Processing Job lifecycle operations.
    """

    def __init__(self):
        self.created = []
        self.completed = []
        self.failed = []

        self.processing_job_id = (
            "processing-job-123"
        )

    def create(
        self,
        *,
        process_type,
        pipeline_version,
        metadata,
    ):
        self.created.append(
            {
                "process_type":
                    process_type,

                "pipeline_version":
                    pipeline_version,

                "metadata":
                    metadata,
            }
        )

        return self.processing_job_id

    def complete(
        self,
        processing_job_id,
    ):
        self.completed.append(
            processing_job_id
        )

    def fail(
        self,
        processing_job_id,
        error,
    ):
        self.failed.append(
            (
                processing_job_id,
                error,
            )
        )


