class RecordFailureDiscoveryService:
    """
    Classify every successfully translated record.
    """

    def run(
        self,
        translator_section,
    ):
        discovery_records = []

        for translator_record in (
            translator_section.translated_records
        ):

            source_object_id = (
                translator_record.source_object_id
            )

            if (
                source_object_id
                == "source-new"
            ):

                sync_state = (
                    SyncState.NEW
                )

                requires_extraction = (
                    True
                )

                knowledge_object_id = (
                    None
                )

                previous_content_hash = (
                    None
                )

            elif (
                source_object_id
                == "source-unchanged"
            ):

                sync_state = (
                    SyncState.UNCHANGED
                )

                requires_extraction = (
                    False
                )

                knowledge_object_id = (
                    "ko-unchanged"
                )

                previous_content_hash = (
                    "unchanged-hash"
                )

            else:

                sync_state = (
                    SyncState.MODIFIED
                )

                requires_extraction = (
                    True
                )

                knowledge_object_id = (
                    "ko-"
                    + source_object_id
                )

                previous_content_hash = (
                    "old-hash-"
                    + source_object_id
                )

            discovery_records.append(
                SimpleNamespace(
                    correlation_id=(
                        translator_record
                        .correlation_id
                    ),

                    sync_state=(
                        sync_state
                    ),

                    requires_extraction=(
                        requires_extraction
                    ),

                    knowledge_object_id=(
                        knowledge_object_id
                    ),

                    previous_content_hash=(
                        previous_content_hash
                    ),

                    comparison_reason=
                        None,
                )
            )

        return SyntheticSection(
            discovery_records=tuple(
                discovery_records
            ),
            record_errors=(),
        )


