"""
AlphaOmega Processing Job Repository

Purpose:
    Provides database persistence operations for AlphaOmega Processing Jobs.

Responsibilities:
    - Create Processing Job records.
    - Mark Processing Jobs completed.
    - Mark Processing Jobs failed.
    - Validate Processing Job identity and expected update results.
    - Own storage-specific lifecycle updates against the processing_jobs table.

Does NOT:
    - Decide when a Processing Job should be created.
    - Coordinate synchronization stages.
    - Determine synchronization success or failure.
    - Execute Connector, Translator, Discovery, Extraction, or Load.
    - Generate synchronization correlation identity.
"""

from datetime import datetime, timezone


class ProcessingJobRepository:
    """
    Persist Processing Job lifecycle state.
    """

    def __init__(
        self,
        client,
    ):
        """
        Initialize the repository.

        Args:
            client:
                Authenticated AlphaOmega database client.
        """

        if client is None:
            raise ValueError(
                "Database client is required."
            )

        self._client = client

    def create(
        self,
        *,
        process_type,
        pipeline_version,
        metadata=None,
    ):
        """
        Create one running Processing Job.

        Returns:
            str:
                Database-generated Processing Job UUID.
        """

        if (
            process_type is None
            or not str(
                process_type
            ).strip()
        ):
            raise ValueError(
                "process_type is required."
            )

        if (
            pipeline_version is None
            or not str(
                pipeline_version
            ).strip()
        ):
            raise ValueError(
                "pipeline_version is required."
            )

        if metadata is None:
            metadata = {}

        response = (
            self._client
            .table(
                "processing_jobs"
            )
            .insert(
                {
                    "process_type":
                        str(
                            process_type
                        ).strip(),

                    "status":
                        "running",

                    "pipeline_version":
                        str(
                            pipeline_version
                        ).strip(),

                    "metadata":
                        metadata,
                }
            )
            .execute()
        )

        records = response.data

        if (
            records is None
            or len(records) != 1
        ):
            raise RuntimeError(
                "Unable to create Processing Job."
            )

        processing_job_id = (
            records[0].get(
                "id"
            )
        )

        if (
            processing_job_id is None
            or not str(
                processing_job_id
            ).strip()
        ):
            raise RuntimeError(
                "Created Processing Job did not return an ID."
            )

        return processing_job_id

    def complete(
        self,
        processing_job_id,
    ):
        """
        Mark one Processing Job completed.
        """

        self._validate_processing_job_id(
            processing_job_id
        )

        completed_at = (
            datetime.now(
                timezone.utc
            ).isoformat()
        )

        response = (
            self._client
            .table(
                "processing_jobs"
            )
            .update(
                {
                    "status":
                        "completed",

                    "completed_at":
                        completed_at,

                    "error_message":
                        None,
                }
            )
            .eq(
                "id",
                processing_job_id,
            )
            .execute()
        )

        self._validate_single_update(
            response=response,
            action="complete",
        )

    def fail(
        self,
        processing_job_id,
        error,
    ):
        """
        Mark one Processing Job failed.
        """

        self._validate_processing_job_id(
            processing_job_id
        )

        if error is None:
            raise ValueError(
                "Processing Job failure error is required."
            )

        completed_at = (
            datetime.now(
                timezone.utc
            ).isoformat()
        )

        response = (
            self._client
            .table(
                "processing_jobs"
            )
            .update(
                {
                    "status":
                        "failed",

                    "completed_at":
                        completed_at,

                    "error_message":
                        str(
                            error
                        ),
                }
            )
            .eq(
                "id",
                processing_job_id,
            )
            .execute()
        )

        self._validate_single_update(
            response=response,
            action="fail",
        )

    @staticmethod
    def _validate_processing_job_id(
        processing_job_id,
    ):
        """
        Validate Processing Job identity.
        """

        if (
            processing_job_id is None
            or not str(
                processing_job_id
            ).strip()
        ):
            raise ValueError(
                "processing_job_id is required."
            )

    @staticmethod
    def _validate_single_update(
        *,
        response,
        action,
    ):
        """
        Verify exactly one Processing Job was updated.
        """

        records = getattr(
            response,
            "data",
            None,
        )

        if (
            records is None
            or len(records) != 1
        ):
            raise RuntimeError(
                f"Unable to {action} Processing Job."
            )

"""
AlphaOmega Text Extractor

Purpose:
    Produces canonical text content from supported source formats.

Responsibilities:
    - Determine whether a file format is supported for text extraction.
    - Extract canonical text from plain-text files.
    - Extract canonical text from HTML.
    - Extract canonical text from DOCX documents.
    - Extract canonical text from PDF documents.
    - Extract canonical text from XLSX workbooks.
    - Reject unsupported extraction formats.

Does NOT:
    - Retrieve source objects.
    - Determine synchronization state.
    - Generate content hashes.
    - Persist Knowledge Objects.
    - Perform AI interpretation or enrichment.
"""

import io
from pathlib import Path

from bs4 import BeautifulSoup
from docx import Document
from openpyxl import load_workbook
from pypdf import PdfReader


class TextExtractor:
    """
    Extract canonical text content from supported file formats.
    """

    extractor_name = "text_extractor"

    supported_extensions = {
        ".txt",
        ".md",
        ".csv",
        ".json",
        ".xml",
        ".docx",
        ".pdf",
        ".xlsx",
        ".html",
        ".htm",
    }

    @classmethod
    def supports(cls, file_name):
        """
        Return True when the file extension is supported.
        """

        extension = Path(file_name).suffix.lower()

        return extension in cls.supported_extensions

    @classmethod
    def extract(cls, file_name, file_bytes):
        """
        Extract canonical text from a supported source object.

        Args:
            file_name:
                Source object filename.

            file_bytes:
                Raw source object content.

        Returns:
            str:
                Extracted canonical text.

        Raises:
            ValueError:
                If the source object's file type is unsupported.
        """

        extension = Path(file_name).suffix.lower()

        if extension in {
            ".txt",
            ".md",
            ".csv",
            ".json",
            ".xml",
        }:
            return cls._extract_txt(file_bytes)

        if extension == ".docx":
            return cls._extract_docx(file_bytes)

        if extension == ".pdf":
            return cls._extract_pdf(file_bytes)

        if extension == ".xlsx":
            return cls._extract_xlsx(file_bytes)

        if extension in {".html", ".htm"}:
            return cls._extract_html(file_bytes)

        raise ValueError(
            f"Unsupported extraction format: '{extension}'."
        )

    @staticmethod
    def _extract_txt(file_bytes):
        """
        Extract UTF-8 text.
        """

        return file_bytes.decode(
            "utf-8",
            errors="ignore",
        )

    @staticmethod
    def _extract_docx(file_bytes):
        """
        Extract non-empty paragraphs from a DOCX document.
        """

        document = Document(
            io.BytesIO(file_bytes)
        )

        return "\n".join(
            paragraph.text
            for paragraph in document.paragraphs
            if paragraph.text.strip()
        )

    @staticmethod
    def _extract_pdf(file_bytes):
        """
        Extract text from populated PDF pages.
        """

        reader = PdfReader(
            io.BytesIO(file_bytes)
        )

        pages = []

        for page in reader.pages:
            text = page.extract_text() or ""

            if text.strip():
                pages.append(text)

        return "\n".join(pages)

    @staticmethod
    def _extract_xlsx(file_bytes):
        """
        Extract populated worksheet cells as canonical text.
        """

        workbook = load_workbook(
            io.BytesIO(file_bytes),
            read_only=True,
            data_only=True,
        )

        rows = []

        for sheet in workbook.worksheets:
            rows.append(
                f"\n--- Sheet: {sheet.title} ---"
            )

            for row in sheet.iter_rows(
                values_only=True
            ):
                values = [
                    str(cell)
                    for cell in row
                    if cell is not None
                ]

                if values:
                    rows.append(
                        " | ".join(values)
                    )

        return "\n".join(rows)

    @staticmethod
    def _extract_html(file_bytes):
        """
        Extract visible text from HTML content.
        """

        soup = BeautifulSoup(
            file_bytes,
            "html.parser",
        )

        return soup.get_text(
            separator="\n"
        )

"""
AlphaOmega Source Container Reconciler

Purpose:
    Compares a validated complete Source Container observation with persisted
    catalog state.

Responsibilities:
    - Identify newly observed Source Containers.
    - Identify existing Source Containers.
    - Identify previously inactive containers that have reappeared.
    - Identify persisted containers absent from the complete observation.
    - Produce reconciliation results required for atomic persistence.

Does NOT:
    - Enumerate Sources of Truth.
    - Validate observation completeness.
    - Persist reconciliation results.
    - Deactivate Source Containers itself.
    - Synchronize content.
"""

class SourceContainerReconciler:
    """
    Compare a validated complete Source Container observation
    with AlphaOmega's existing Source Container Catalog.

    This component determines required catalog changes.

    It does not:
        - enumerate a Source of Truth
        - validate the observation
        - access the database
        - write catalog changes
        - create Processing Jobs
    """

    def reconcile(
        self,
        *,
        observed_containers,
        existing_containers,
    ):

        if not isinstance(
            observed_containers,
            list,
        ):
            raise ValueError(
                "observed_containers must be a list"
            )

        if not isinstance(
            existing_containers,
            list,
        ):
            raise ValueError(
                "existing_containers must be a list"
            )

        existing_by_identity = {}

        for existing in existing_containers:

            source_object_id = (
                existing.get(
                    "source_object_id"
                )
            )

            if not source_object_id:
                raise ValueError(
                    "Existing Source Container is missing "
                    "source_object_id"
                )

            if (
                source_object_id
                in existing_by_identity
            ):
                raise ValueError(
                    "Duplicate existing Source Container "
                    f"identity: {source_object_id}"
                )

            existing_by_identity[
                source_object_id
            ] = existing

        observed_ids = set()

        new = []
        existing = []
        reappearing = []
        absent = []

        for observed in observed_containers:

            source_object_id = (
                observed.get(
                    "source_object_id"
                )
            )

            if not source_object_id:
                raise ValueError(
                    "Observed Source Container is missing "
                    "source_object_id"
                )

            if source_object_id in observed_ids:
                raise ValueError(
                    "Duplicate observed Source Container "
                    f"identity: {source_object_id}"
                )

            observed_ids.add(
                source_object_id
            )

            saved = (
                existing_by_identity.get(
                    source_object_id
                )
            )

            if saved is None:

                new.append(
                    {
                        "observed":
                            observed,
                    }
                )

                continue

            if (
                saved.get("is_active")
                is False
            ):

                reappearing.append(
                    {
                        "existing":
                            saved,

                        "observed":
                            observed,
                    }
                )

                continue

            existing.append(
                {
                    "existing":
                        saved,

                    "observed":
                        observed,
                }
            )

        for saved in existing_containers:

            source_object_id = (
                saved["source_object_id"]
            )

            if (
                source_object_id
                not in observed_ids
                and saved.get("is_active") is True
            ):

                absent.append(
                    {
                        "existing":
                            saved,
                    }
                )

        return {
            "new":
                new,

            "existing":
                existing,

            "reappearing":
                reappearing,

            "absent":
                absent,
        }
